package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	line, _ := reader.ReadString('\n')
	line = line[:len(line)-1] // remove newline

	a := make([]int, 6)
	for i, r := range line {
		a[i], _ = strconv.Atoi(string(r))
	}

	sum1 := a[0] + a[1] + a[2]
	sum2 := a[3] + a[4] + a[5]

	if sum1 == sum2 {
		fmt.Println(0)
		return
	}

	a1 := []int{a[0], a[1], a[2]}
	a2 := []int{a[3], a[4], a[5]}
	sort.Ints(a1)
	sort.Ints(a2)

	changes := make([]int, 6)
	if sum1 > sum2 {
		for k := 0; k < 3; k++ {
			changes[k] = a1[k]
			changes[k+3] = 9 - a2[k]
		}
	} else {
		for k := 0; k < 3; k++ {
			changes[k] = a2[k]
			changes[k+3] = 9 - a1[k]
		}
	}

	sort.Ints(changes)

	dif := sum1 - sum2
	if dif < 0 {
		dif = -dif
	}

	sumdif := 0
	answer := 0
	for i := 5; sumdif < dif; i-- {
		sumdif += changes[i]
		answer++
	}

	fmt.Println(answer)
}

